for(const id of Object.keys(banks))banks[id].push(...tfBanks[id]);
export function createDemoQuestions(materialId,type,count){let bank=banks[materialId]||(type==='T/F'?tfBanks[materialId]:null);if(!bank)return null;let filtered;if(type==='혼합형'){const types=['3지선다','단답형','T/F','서술형','빈칸 넣기'];filtered=[];for(let i=0;i<3;i++)for(const t of types){const q=bank.filter(q=>q.type===t)[i];if(q)filtered.push(q)}}else filtered=bank.filter(q=>q.type===type);if(!Number.isInteger(count)||count<1||count>filtered.length)throw new Error(`시연 문항은 ${type==='혼합형'?'혼합형 최대 '+bank.length+'개':type+' 최대 '+filtered.length+'개'}입니다.`);return filtered.slice(0,count).map(q=>({...structuredClone(q),id:crypto.randomUUID(),sourcePage:q.page}))}
